import React, { useEffect, useState } from "react";
import {
  View,
  Text,
  StyleSheet,
  Pressable,
  Alert,
  ActivityIndicator,
} from "react-native";
import { router } from "expo-router";
import {
  hasPin,
  verifyPin,
} from "../services/pin.service";

const C = {
  bg: "#0B0D12",
  card: "#151922",
  border: "#292F3D",
  purple: "#7785FF",
  white: "#F5F7FA",
  muted: "#9299AA",
  red: "#F97066",
};

const PIN_LENGTH = 6;

export default function LockScreen() {
  const [pin, setPin] = useState("");
  const [loading, setLoading] = useState(false);
  const [checking, setChecking] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    let active = true;

    async function checkSetup() {
      try {
        const configured = await hasPin();

        if (!active) return;

        if (!configured) {
          router.replace("/setup-pin");
          return;
        }
      } catch (err) {
        console.error("PIN setup check failed:", err);

        if (active) {
          setError("Unable to check PIN setup. Please retry.");
        }
      } finally {
        if (active) setChecking(false);
      }
    }

    checkSetup();

    return () => {
      active = false;
    };
  }, []);

  async function pressKey(key: string) {
    if (loading || checking) return;

    if (key === "delete") {
      setPin((current) => current.slice(0, -1));
      setError("");
      return;
    }

    if (!/^\d$/.test(key) || pin.length >= PIN_LENGTH) {
      return;
    }

    const nextPin = pin + key;
    setPin(nextPin);
    setError("");

    if (nextPin.length !== PIN_LENGTH) return;

    setLoading(true);

    try {
      const valid = await verifyPin(nextPin);

      if (valid) {
        // Allow the app's protected tabs to be opened
        // only after successful PIN verification.
        router.replace("/(tabs)");
      } else {
        setPin("");
        setError("Incorrect PIN. Please try again.");
      }
    } catch (err) {
      setPin("");

      setError(
        err instanceof Error
          ? err.message
          : "PIN verification failed."
      );
    } finally {
      setLoading(false);
    }
  }

  if (checking) {
    return (
      <View style={[s.screen, s.loadingScreen]}>
        <ActivityIndicator size="large" color={C.purple} />
        <Text style={s.loadingText}>Checking security...</Text>
      </View>
    );
  }

  return (
    <View style={s.screen}>
      <View style={s.top}>
        <View style={s.logo}>
          <Text style={s.logoText}>D</Text>
        </View>

        <Text style={s.brand}>DESKPILOT</Text>
        <Text style={s.tagline}>
          YOUR LAPTOP, UNDER YOUR CONTROL
        </Text>
      </View>

      <View style={s.center}>
        <View style={s.lockIcon}>
          <Text style={s.lockEmoji}>⌑</Text>
        </View>

        <Text style={s.title}>Welcome back</Text>

        <Text style={s.subtitle}>
          Enter your 6-digit PIN to continue
        </Text>

        <View style={s.indicators}>
          {Array.from({ length: PIN_LENGTH }, (_, index) => (
            <View
              key={index}
              style={[
                s.indicator,
                pin.length > index && s.indicatorFilled,
              ]}
            />
          ))}
        </View>

        <View style={s.keypad}>
          {[
            "1", "2", "3",
            "4", "5", "6",
            "7", "8", "9",
            "help", "0", "delete",
          ].map((key) => (
            <Pressable
              key={key}
              style={[
                s.key,
                loading && s.disabledKey,
              ]}
              disabled={loading}
              onPress={() => {
                if (key === "help") {
                  Alert.alert(
                    "PIN assistance",
                    "If you forgot your PIN, use the app's authorized recovery process. Resetting the PIN must not bypass account authentication."
                  );
                } else {
                  pressKey(key);
                }
              }}
              accessibilityRole="button"
              accessibilityLabel={
                key === "delete"
                  ? "Delete last digit"
                  : key === "help"
                    ? "PIN help"
                    : key
              }
            >
              <Text style={s.keyText}>
                {key === "delete"
                  ? "⌫"
                  : key === "help"
                    ? "?"
                    : key}
              </Text>
            </Pressable>
          ))}
        </View>

        {loading && (
          <View style={s.statusRow}>
            <ActivityIndicator size="small" color={C.purple} />
            <Text style={s.statusText}>Verifying PIN...</Text>
          </View>
        )}

        {!!error && (
          <Text accessibilityRole="alert" style={s.errorText}>
            {error}
          </Text>
        )}

        <Pressable
          onPress={() => {
            Alert.alert(
              "Forgot PIN?",
              "PIN reset needs an authorized recovery flow. For now, use the account recovery process rather than bypassing the lock."
            );
          }}
          style={s.forgot}
        >
          <Text style={s.forgotText}>Forgot PIN?</Text>
        </Pressable>
      </View>

      <View style={s.bottom}>
        <View style={s.secureRow}>
          <Text style={s.secureIcon}>◆</Text>
          <Text style={s.secureText}>
            YOUR ACCESS, YOUR CONTROL
          </Text>
        </View>

        <Text style={s.version}>
          DESKPILOT • SECURE ACCESS
        </Text>
      </View>
    </View>
  );
}

