const LOCKED_UNTIL_KEY = "deskpilot_pin_locked_until";

const PIN_LENGTH = 4;
const MAX_FAILED_ATTEMPTS = 5;
const LOCKOUT_DURATION_MS = 30_000;

function isValidPin(pin: string): boolean {
  return new RegExp(`^\\d{${PIN_LENGTH}}$`).test(pin);
}

async function hashPin(pin: string, salt: string): Promise<string> {
  return Crypto.digestStringAsync(
    Crypto.CryptoDigestAlgorithm.SHA256,
    `${salt}:${pin}`
  );
}

/**
 * Checks whether a PIN has already been configured.
 */
export async function hasPin(): Promise<boolean> {
  const hash = await SecureStore.getItemAsync(PIN_HASH_KEY);
  const salt = await SecureStore.getItemAsync(PIN_SALT_KEY);

  return Boolean(hash && salt);
}

/**
 * Saves a new 6-digit PIN as a salted hash.
 * Never stores the original PIN.
 */
export async function savePin(pin: string): Promise<void> {
  if (!isValidPin(pin)) {
    throw new Error("PIN must contain exactly 6 digits.");
  }

  const salt = Crypto.randomUUID();
  const hash = await hashPin(pin, salt);

  await SecureStore.setItemAsync(PIN_SALT_KEY, salt);
  await SecureStore.setItemAsync(PIN_HASH_KEY, hash);
  await SecureStore.setItemAsync(FAILED_ATTEMPTS_KEY, "0");
  await SecureStore.deleteItemAsync(LOCKED_UNTIL_KEY);
}

/**
 * Verifies a PIN and applies a temporary lockout
 * after repeated incorrect attempts.
 */
export async function verifyPin(pin: string): Promise<boolean> {
  if (!isValidPin(pin)) {
    return false;
  }

  const lockedUntilValue = await SecureStore.getItemAsync(
    LOCKED_UNTIL_KEY
  );

  const lockedUntil = Number(lockedUntilValue || "0");

  if (Date.now() < lockedUntil) {
    const remainingSeconds = Math.ceil(
      (lockedUntil - Date.now()) / 1000
    );

    throw new Error(
      `Too many attempts. Try again in ${remainingSeconds} seconds.`
    );
  }

  const salt = await SecureStore.getItemAsync(PIN_SALT_KEY);
  const savedHash = await SecureStore.getItemAsync(PIN_HASH_KEY);

  if (!salt || !savedHash) {
    throw new Error("No PIN configured. Please set up your PIN first.");
  }

  const enteredHash = await hashPin(pin, salt);

  if (enteredHash === savedHash) {
    await SecureStore.setItemAsync(FAILED_ATTEMPTS_KEY, "0");
    await SecureStore.deleteItemAsync(LOCKED_UNTIL_KEY);

    return true;
  }

  const attemptsValue = await SecureStore.getItemAsync(
    FAILED_ATTEMPTS_KEY
  );

  const attempts = Number(attemptsValue || "0") + 1;

  if (attempts >= MAX_FAILED_ATTEMPTS) {
    const newLockedUntil = Date.now() + LOCKOUT_DURATION_MS;

    await SecureStore.setItemAsync(
      LOCKED_UNTIL_KEY,
      String(newLockedUntil)
    );

    await SecureStore.setItemAsync(FAILED_ATTEMPTS_KEY, "0");

    throw new Error(
      "Too many incorrect attempts. Please wait 30 seconds."
    );
  }

  await SecureStore.setItemAsync(
    FAILED_ATTEMPTS_KEY,
    String(attempts)
  );

  return false;
}

/**
 * Changes the PIN only after verifying the current PIN.
 */
export async function changePin(
  currentPin: string,
  newPin: string
): Promise<void> {
  const isCurrentPinValid = await verifyPin(currentPin);

  if (!isCurrentPinValid) {
    throw new Error("Current PIN is incorrect.");
  }

  if (!isValidPin(newPin)) {
    throw new Error("New PIN must contain exactly 6 digits.");
  }

  await savePin(newPin);
}

/**
 * Removes the locally stored PIN.
 * Call only after the user has been authenticated
 * and your app's security flow allows a PIN reset.
 */
export async function removePin(): Promise<void> {
  await SecureStore.deleteItemAsync(PIN_HASH_KEY);
  await SecureStore.deleteItemAsync(PIN_SALT_KEY);
  await SecureStore.deleteItemAsync(FAILED_ATTEMPTS_KEY);
  await SecureStore.deleteItemAsync(LOCKED_UNTIL_KEY);
}

import React, { useState } from "react";
import {
    View,
    Text,
    StyleSheet,
    Pressable,
    Alert,
    ActivityIndicator,
} from "react-native";
import { router, useLocalSearchParams } from "expo-router";
import { savePin } from "../services/pin.service";

const C = {
    bg: "#0B0D12",
    card: "#151922",
    border: "#292F3D",
    purple: "#7785FF",
    white: "#F5F7FA",
    muted: "#9299AA",
    red: "#F97066",
};

const PIN_LENGTH = 4;

const KEYS = [
    "1", "2", "3",
    "4", "5", "6",
    "7", "8", "9",
    "delete", "0", "confirm",
];

export default function ConfirmPinScreen() {
    const params = useLocalSearchParams<{ pin?: string | string[] }>();

    const originalPin = Array.isArray(params.pin)
        ? params.pin[0]
        : params.pin;

    const [confirmPin, setConfirmPin] = useState("");
    const [saving, setSaving] = useState(false);

    async function handleKey(key: string) {
        if (saving) return;

        if (key === "delete") {
            setConfirmPin((current) => current.slice(0, -1));
            return;
        }

        if (key === "confirm") {
            if (!originalPin || originalPin.length !== PIN_LENGTH) {
                Alert.alert(
                    "Setup expired",
                    "Please create your PIN again.",
                    [
                        {
                            text: "OK",
                            onPress: () => router.replace("/setup-pin"),
                        },
                    ]
                );
                return;
            }

            if (confirmPin.length !== PIN_LENGTH) {
                Alert.alert(
                    "PIN required",
                    "Please enter all 6 digits."
                );
                return;
            }

            if (confirmPin !== originalPin) {
                setConfirmPin("");

                Alert.alert(
                    "PIN mismatch",
                    "The PINs do not match. Please try again."
                );
                return;
            }

            try {
                setSaving(true);

                await savePin(confirmPin);

                router.replace("/unlock");
            } catch (error) {
                console.error("PIN setup failed:", error);

                Alert.alert(
                    "Setup failed",
                    "PIN could not be saved securely. Please try again."
                );
            } finally {
                setSaving(false);
            }

            return;
        }

        if (/^\d$/.test(key) && confirmPin.length < PIN_LENGTH) {
            setConfirmPin((current) => current + key);
        }
    }

    return (
        <View style={s.screen}>
            <Pressable
                onPress={() => router.back()}
                style={s.back}
                disabled={saving}
            >
                <Text style={s.backText}>‹  Back</Text>
            </Pressable>

            <View style={s.brandBlock}>
                <View style={s.logo}>
                    <Text style={s.logoText}>D</Text>
                </View>

                <Text style={s.brand}>DESKPILOT</Text>
                <Text style={s.eyebrow}>SECURITY SETUP</Text>
            </View>

            <View style={s.main}>
                <Text style={s.title}>Confirm your PIN</Text>

                <Text style={s.subtitle}>
                    Enter the same 6-digit PIN one more time.
                </Text>

                <View style={s.indicators}>
                    {Array.from({ length: PIN_LENGTH }, (_, i) => (
                        <View
                            key={i}
                            style={[
                                s.dot,
                                confirmPin.length > i && s.dotFilled,
                            ]}
                        />
                    ))}
                </View>

                <View style={s.keypad}>
                    {KEYS.map((key) => (
                        <Pressable
                            key={key}
                            onPress={() => handleKey(key)}
                            disabled={saving}
                            accessibilityRole="button"
                            accessibilityLabel={
                                key === "delete"
                                    ? "Delete last digit"
                                    : key === "confirm"
                                        ? "Confirm PIN"
                                        : key
                            }
                            style={[
                                s.key,
                                saving && s.disabledKey,
                            ]}
                        >
                            <Text
                                style={[
                                    s.keyText,
                                    key === "confirm" && s.confirmText,
                                ]}
                            >
                                {key === "delete"
                                    ? "⌫"
                                    : key === "confirm"
                                        ? "✓"
                                        : key}
                            </Text>
                        </Pressable>
                    ))}
                </View>

                {saving && (
                    <View style={s.saving}>
                        <ActivityIndicator color={C.purple} />
                        <Text style={s.savingText}>
                            Saving your PIN securely...
                        </Text>
                    </View>
                )}
            </View>

            <Text style={s.footer}>
                DESKPILOT • PRIVATE BY DESIGN
            </Text>
        </View>
    );
}

