import { hasPin } from "../services/pin.service";

export default function RootLayout() {
  const pathname = usePathname();
  const [checking, setChecking] = useState(true);
  const [configured, setConfigured] = useState(false);

  const appState = useRef(AppState.currentState);
  const wasBackgrounded = useRef(false);

  useEffect(() => {
    let active = true;

    async function checkPinSetup() {
      try {
        const exists = await hasPin();

        if (!active) return;

        setConfigured(exists);
      } catch (error) {
        console.error("PIN setup check failed:", error);
        setConfigured(false);
      } finally {
        if (active) setChecking(false);
      }
    }

    checkPinSetup();

    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    const subscription = AppState.addEventListener(
      "change",
      (nextState: AppStateStatus) => {
        const previousState = appState.current;

        if (
          previousState === "active" &&
          (nextState === "background" ||
            nextState === "inactive")
        ) {
          wasBackgrounded.current = true;
        }

        if (
          nextState === "active" &&
          wasBackgrounded.current
        ) {
          wasBackgrounded.current = false;

          if (configured) {
            router.replace("/");
          }
        }

        appState.current = nextState;
      }
    );

    return () => subscription.remove();
  }, [configured]);

  useEffect(() => {
    if (checking) return;

    const publicSetupRoutes = [
      "/setup-pin",
      "/confirm-pin",
      "/unlock",
    ];

    if (!configured) {
      if (pathname !== "/setup-pin" &&
          pathname !== "/confirm-pin" &&
          pathname !== "/unlock") {
        router.replace("/setup-pin");
      }

      return;
    }

    // PIN already exists: prevent opening setup directly.
    if (pathname === "/setup-pin") {
      router.replace("/");
    }
  }, [checking, configured, pathname]);

  return (
    <Stack screenOptions={{ headerShown: false }}>
      <Stack.Screen name="index" />
      <Stack.Screen name="home" />
      <Stack.Screen name="(tabs)" />
      <Stack.Screen name="apps/add" />
      <Stack.Screen name="setup-pin" />
      <Stack.Screen name="confirm-pin" />
      <Stack.Screen name="unlock" />
      <Stack.Screen name="connection" />
      <Stack.Screen name="settings" />
      <Stack.Screen name="activity" />
      <Stack.Screen name="about" />
      <Stack.Screen name="change-pin" />
    </Stack>
  );
}

