import React, { useState } from "react";
import {
  View,
  Text,
  StyleSheet,
  Pressable,
  Alert,
} from "react-native";
import { router } from "expo-router";

const C = {
  bg: "#0B0D12",
  card: "#151922",
  border: "#292F3D",
  purple: "#7785FF",
  white: "#F5F7FA",
  muted: "#9299AA",
  red: "#F97066",
};

export default function LockScreen() {
  const [pin, setPin] = useState("");
  const [loading, setLoading] = useState(false);

  function pressKey(key: string) {
    if (key === "delete") {
      setPin((current) => current.slice(0, -1));
      return;
    }

    if (pin.length >= 4 || loading) return;

    const nextPin = pin + key;
    setPin(nextPin);

    if (nextPin.length === 4) {
      setLoading(true);

      // UI preview only: actual PIN verification baad mein.
      setTimeout(() => {
        setLoading(false);
        setPin("");

        Alert.alert(
          "Demo PIN",
          "PIN verification abhi connect nahi hai. Dashboard preview khol rahe hain.",
          [
            {
              text: "Continue",
              onPress: () => router.replace("/(tabs)"),
            },
            {
              text: "Cancel",
              style: "cancel",
            },
          ]
        );
      }, 250);
    }
  }

  return (
    <View style={s.screen}>
      <View style={s.top}>
        <View style={s.logo}>
          <Text style={s.logoText}>D</Text>
        </View>
        <Text style={s.brand}>DESKPILOT</Text>
        <Text style={s.tagline}>YOUR LAPTOP, UNDER YOUR CONTROL</Text>
      </View>

      <View style={s.center}>
        <View style={s.lockIcon}>
          <Text style={s.lockEmoji}>⌑</Text>
        </View>

        <Text style={s.title}>Welcome back</Text>
        <Text style={s.subtitle}>
          Enter your 4-digit PIN to continue
        </Text>

        <View style={s.indicators}>
          {[0, 1, 2, 3].map((index) => (
            <View
              key={index}
              style={[
                s.indicator,
                pin.length > index && s.indicatorFilled,
              ]}
            />
          ))}
        </View>

        <View style={s.keypad}>
          {["1", "2", "3", "4", "5", "6", "7", "8", "9", "help", "0", "delete"].map(
            (key) => (
              <Pressable
                key={key}
                style={s.key}
                onPress={() => {
                  if (key === "help") {
                    router.push("/setup-pin");
                  } else {
                    pressKey(key);
                  }
                }}
              >
                <Text style={s.keyText}>
                  {key === "delete"
                    ? "⌫"
                    : key === "help"
                      ? "?"
                      : key}
                </Text>
              </Pressable>
            )
          )}
        </View>

        <Pressable
          onPress={() => router.push("/setup-pin")}
          style={s.forgot}
        >
          <Text style={s.forgotText}>Forgot PIN?  Set up again</Text>
        </Pressable>
      </View>

      <View style={s.bottom}>
        <View style={s.secureRow}>
          <Text style={s.secureIcon}>◆</Text>
          <Text style={s.secureText}>YOUR ACCESS, YOUR CONTROL</Text>
        </View>
        <Text style={s.version}>DESKPILOT • UI PREVIEW</Text>
      </View>
    </View>
  );
}

