import React, { useState } from "react";
import {
  View,
  Text,
  StyleSheet,
  Pressable,
  Alert,
  ActivityIndicator,
} from "react-native";
import { router, useLocalSearchParams } from "expo-router";
import { savePin } from "../services/pin.service";

const C = {
  bg: "#0B0D12",
  card: "#151922",
  border: "#292F3D",
  purple: "#7785FF",
  white: "#F5F7FA",
  muted: "#9299AA",
  red: "#F97066",
};

const PIN_LENGTH = 6;

const KEYS = [
  "1", "2", "3",
  "4", "5", "6",
  "7", "8", "9",
  "delete", "0", "confirm",
];

export default function ConfirmPinScreen() {
  const params = useLocalSearchParams<{ pin?: string | string[] }>();

  const originalPin = Array.isArray(params.pin)
    ? params.pin[0]
    : params.pin;

  const [confirmPin, setConfirmPin] = useState("");
  const [saving, setSaving] = useState(false);

  async function handleKey(key: string) {
    if (saving) return;

    if (key === "delete") {
      setConfirmPin((current) => current.slice(0, -1));
      return;
    }

    if (key === "confirm") {
      if (!originalPin || originalPin.length !== PIN_LENGTH) {
        Alert.alert(
          "Setup expired",
          "Please create your PIN again.",
          [
            {
              text: "OK",
              onPress: () => router.replace("/setup-pin"),
            },
          ]
        );
        return;
      }

      if (confirmPin.length !== PIN_LENGTH) {
        Alert.alert(
          "PIN required",
          "Please enter all 6 digits."
        );
        return;
      }

      if (confirmPin !== originalPin) {
        setConfirmPin("");

        Alert.alert(
          "PIN mismatch",
          "The PINs do not match. Please try again."
        );
        return;
      }

      try {
        setSaving(true);

        await savePin(confirmPin);

        router.replace("/unlock");
      } catch (error) {
        console.error("PIN setup failed:", error);

        Alert.alert(
          "Setup failed",
          "PIN could not be saved securely. Please try again."
        );
      } finally {
        setSaving(false);
      }

      return;
    }

    if (/^\d$/.test(key) && confirmPin.length < PIN_LENGTH) {
      setConfirmPin((current) => current + key);
    }
  }

  return (
    <View style={s.screen}>
      <Pressable
        onPress={() => router.back()}
        style={s.back}
        disabled={saving}
      >
        <Text style={s.backText}>‹  Back</Text>
      </Pressable>

      <View style={s.brandBlock}>
        <View style={s.logo}>
          <Text style={s.logoText}>D</Text>
        </View>

        <Text style={s.brand}>DESKPILOT</Text>
        <Text style={s.eyebrow}>SECURITY SETUP</Text>
      </View>

      <View style={s.main}>
        <Text style={s.title}>Confirm your PIN</Text>

        <Text style={s.subtitle}>
          Enter the same 6-digit PIN one more time.
        </Text>

        <View style={s.indicators}>
          {Array.from({ length: PIN_LENGTH }, (_, i) => (
            <View
              key={i}
              style={[
                s.dot,
                confirmPin.length > i && s.dotFilled,
              ]}
            />
          ))}
        </View>

        <View style={s.keypad}>
          {KEYS.map((key) => (
            <Pressable
              key={key}
              onPress={() => handleKey(key)}
              disabled={saving}
              accessibilityRole="button"
              accessibilityLabel={
                key === "delete"
                  ? "Delete last digit"
                  : key === "confirm"
                  ? "Confirm PIN"
                  : key
              }
              style={[
                s.key,
                saving && s.disabledKey,
              ]}
            >
              <Text
                style={[
                  s.keyText,
                  key === "confirm" && s.confirmText,
                ]}
              >
                {key === "delete"
                  ? "⌫"
                  : key === "confirm"
                  ? "✓"
                  : key}
              </Text>
            </Pressable>
          ))}
        </View>

        {saving && (
          <View style={s.saving}>
            <ActivityIndicator color={C.purple} />
            <Text style={s.savingText}>
              Saving your PIN securely...
            </Text>
          </View>
        )}
      </View>

      <Text style={s.footer}>
        DESKPILOT • PRIVATE BY DESIGN
      </Text>
    </View>
  );
}

